'use strict';

const $ = (q, el=document) => el.querySelector(q);
const $$ = (q, el=document) => [...el.querySelectorAll(q)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name, cls='') => `<svg class="ico ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const mark = '<img src="/static/mark.svg" alt="">';
const state = {data:null, view:'dashboard', demo:false, modal:null, detailTab:'overview', serverId:null,
  filePath:'', editorPath:null, dirty:false, range:24, zoom:1, graphSignature:'', loading:false};
const names = {dashboard:'Dashboard',network:'Netzwerk',servers:'Server & Proxys',agents:'Agenten',routines:'Routinen',activity:'Aktivitäten',settings:'Einstellungen'};
const symbols = {dashboard:'grid',network:'network',servers:'server',agents:'chip',routines:'clock',activity:'activity',settings:'settings'};
const fmt = n => new Intl.NumberFormat('de-DE', {maximumFractionDigits:1}).format(n || 0);
const date = t => new Date(t*1000).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
const ago = t => {const s=Math.max(0,Math.floor(Date.now()/1000-t));return s<60?'Gerade eben':s<3600?`vor ${Math.floor(s/60)} Min.`:s<86400?`vor ${Math.floor(s/3600)} Std.`:date(t);};
const bytes = n => n>=1e6?`${(n/1e6).toFixed(1)} MB`:n>=1e3?`${(n/1e3).toFixed(1)} KB`:`${n} B`;
const server = id => state.data.servers.find(s=>s.id===id);
const agent = id => state.data.agents.find(a=>a.id===id);
const toast = (message,error=false) => {const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'close':'check')+`<span>${esc(message)}</span>`;$('#toast-root').append(el);while($('#toast-root').children.length>3)$('#toast-root').firstElementChild.remove();setTimeout(()=>el.remove(),6500);};

async function api(path, method='GET', body) {
  const response = await fetch('/api'+path,{method,headers:body!==undefined?{'Content-Type':'application/json'}:{},body:body!==undefined?JSON.stringify(body):undefined});
  const data = await response.json().catch(()=>({detail:'Unerwartete Serverantwort'}));
  if (!response.ok) {
    if(response.status===401 && path!='/login') showLogin();
    throw new Error(typeof data.detail==='string'?data.detail:(data.detail?.[0]?.msg || 'Anfrage fehlgeschlagen'));
  }
  return data;
}

async function job(request, timeout=95000) {
  const {job_id} = await request;
  const start = Date.now();
  while(Date.now()-start<timeout) {
    const result=await api('/jobs/'+job_id);
    if(result.status==='done') return result.result.data;
    if(result.status==='failed') throw new Error(result.result?.error || 'Auftrag fehlgeschlagen');
    await new Promise(resolve=>setTimeout(resolve,650));
  }
  throw new Error('Auftrag läuft noch oder Agent antwortet nicht. Ergebnis später in den Aktivitäten prüfen.');
}

function statusBadge(s) {
  const map={running:['Online',''],stopped:['Gestoppt','muted'],unknown:['Agent offline','muted'],installing:['Installation …','purple'],error:['Fehler','warning'],missing:['Fehlt auf Agent','warning']};
  const [text,cls]=map[s.status]||['Unbekannt','muted'];
  return `<span class="pill ${cls}"><i class="dot ${s.status==='running'?'':s.status==='installing'?'warn':'off'}"></i>${text}</span>`;
}

function showLogin() {
  closeModal(true);
  state.data=null;
  $('#app').innerHTML=`<div class="login-page"><form id="login-form" class="login-card"><div class="brand">${mark}NOVA</div><div class="eyebrow">YOUR NETWORK. YOUR UNIVERSE.</div><h1>Willkommen zurück.</h1><p>Melde dich an und bring deine Minecraft-Welten zusammen.</p><div id="login-error"></div><label class="form-field"><span>Admin-Passwort</span><input type="password" name="password" autocomplete="current-password" required autofocus placeholder="Dein Passwort"></label><button class="button primary" type="submit">Zentrale öffnen ${icon('arrow')}</button><footer>NOVA CONTROL PLANE · v0.1.0</footer></form></div>`;
  $('#login-form').onsubmit=async e=>{e.preventDefault();const button=$('button',e.target);button.disabled=true;try{await api('/login','POST',{password:e.target.password.value});await boot();}catch(err){$('#login-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;}finally{button.disabled=false;}};
}

function shell() {
  $('#app').innerHTML=`<aside class="sidebar"><a href="#dashboard" class="brand" aria-label="NOVA Dashboard">${mark}NOVA<span>MC</span></a>
    <div class="workspace"><div class="square">N</div><div><strong>Mein Netzwerk</strong><small>Minecraft Network</small></div>${icon('network')}</div>
    <div class="nav-label">WORKSPACE</div><nav>${['dashboard','network','servers','agents','routines'].map(v=>`<button class="nav-item" data-nav="${v}">${icon(symbols[v])}<span>${names[v]}</span>${v==='servers'?'<span class="count" data-count="servers"></span>':v==='agents'?'<span class="count" data-count="agents"></span>':''}</button>`).join('')}</nav>
    <div class="nav-label second">VERWALTUNG</div><nav>${['activity','settings'].map(v=>`<button class="nav-item" data-nav="${v}">${icon(symbols[v])}${names[v]}</button>`).join('')}</nav>
    <div class="sidebar-bottom"><button class="nav-item" data-action="guide">${icon('book')}Dokumentation ${icon('arrow')}</button><div class="connection"><strong><i class="dot"></i>${state.demo?'Demomodus aktiv':'Zentrale verbunden'}</strong>${state.demo?'Beispieldaten · lokal ausprobierbar':'Dein Universum. Unter Kontrolle.'}</div><div class="profile"><div class="avatar">AD</div><div><strong>Administrator</strong><small>${state.demo?'Demo Workspace':'Netzwerk-Owner'}</small></div><button class="icon-btn" data-action="logout" title="Abmelden">${icon('logout')}</button></div></div></aside>
    <div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Menü öffnen">${icon('menu')}</button>${icon('globe')}<span>Workspace</span>${icon('chevron')}<strong id="crumb">Dashboard</strong></div><div class="top-actions"><button class="search-button" data-action="search" aria-label="Suchen (Strg+K)">${icon('search')}<span>Dein Netzwerk durchsuchen</span><kbd>⌘ K</kbd></button><div class="v-divider"></div><button class="icon-btn bell" data-nav="activity" aria-label="Aktivitäten">${icon('bell')}</button><div class="avatar mini-avatar">AD</div></div></header><main id="content" class="content"></main></div>`;
}

function title(heading, subtitle, actions='') {
  return `<div class="page-title"><div><div class="eyebrow">MINECRAFT NETWORK MANAGER</div><h1>${heading}</h1><p>${subtitle}</p></div><div class="page-actions">${actions}</div></div>`;
}
const createButton = `<button class="button primary" data-action="create">${icon('plus')}Instanz erstellen</button>`;
const pairButton = `<button class="button secondary" data-action="pair">${icon('plus')}Agent verbinden</button>`;
function footer(){return `<footer class="footer"><span>NOVA <span>© ${new Date().getFullYear()}</span> <span>·</span> Für deine nächste große Welt.</span><span><i class="dot"></i>${state.demo?'DEMO · SIMULIERTE METRIKEN':'LIVE · ALLE 8 SEKUNDEN'} <span>v0.1.0</span></span></footer>`;}
function empty(heading, text, action=''){return `<div class="empty">${icon('network')}<h3>${heading}</h3><p>${text}</p>${action}</div>`;}

function statCard(label,value,unit,iconName,color,foot,bars) {
  return `<article class="stat" style="--color:${color}"><div class="stat-label">${label}<span class="stat-icon">${icon(iconName)}</span></div><div class="stat-value">${value}<span class="unit">${unit}</span></div><div class="stat-foot">${foot}${bars?`<span class="mini-bars">${[4,8,5,11,8,12,10,13,9,12].map((h,i)=>`<i style="height:${h}px;opacity:${.25+i*.06}"></i>`).join('')}</span>`:''}</div></article>`;
}
function stats() {
 const d=state.data, running=d.servers.filter(s=>s.status==='running').length;
 return `<div class="stats">${statCard('Spieler online',fmt(d.players),'/ '+fmt(d.servers.filter(s=>s.software==='velocity').reduce((n,s)=>n+(s.metrics.max_players||0),0)||d.servers.filter(s=>s.software==='paper').reduce((n,s)=>n+(s.metrics.max_players||0),0)),'users','#a48bfa',`<b>${icon('activity')} Netzwerkweit</b> · ${state.demo?'Demowerte':'Status-Ping'}`,true)}${statCard('Aktive Instanzen',running,`/ ${d.servers.length}`,'server','#729ffc',`<b>${d.servers.filter(s=>s.software==='velocity').length} Proxy</b> · ${d.servers.filter(s=>s.software==='paper').length} Minecraft-Server`,false)}${statCard('CPU-Auslastung',fmt(d.cpu),'%','chip','#b98be9',`Ø über ${d.agents.filter(a=>a.online).length} verbundene Agenten`,true)}${statCard('Arbeitsspeicher',fmt(d.ram_used),'GB','ram','#62b9cd',`von ${fmt(d.ram_total)} GB verfügbar`,true)}</div>`;
}

function graphCard(full=false){return `<section class="card graph-card ${full?'full-network':''}"><div class="card-head"><div><div class="card-title">${icon('network')}Deine Infrastruktur <span class="pill purple">${state.data.agents.length+1} Nodes</span></div><p class="card-subtitle">Jede Welt verbunden. Alles an einem Ort.</p></div><div class="graph-toolbar"><span class="live-label"><i class="dot"></i>${state.demo?'DEMO':'LIVE'}</span>${!full?`<button class="icon-btn" data-nav="network" title="Netzwerk vergrößern">${icon('expand')}</button>`:''}</div></div><div class="graph-stage"><svg id="topology" class="topology" viewBox="0 0 800 340" role="img" aria-label="Interaktive Netzwerkkarte: Zentrale, Agenten und Minecraft-Instanzen"></svg><div class="graph-hint">${icon('expand')}Nodes ziehen, doppelklicken zum Öffnen</div><div class="graph-controls"><button class="icon-btn" data-action="zoom-in" title="Vergrößern">+</button><button class="icon-btn" data-action="zoom-out" title="Verkleinern">−</button><button class="icon-btn" data-action="reset-graph" title="Anordnung zurücksetzen">${icon('expand')}</button></div></div><div class="graph-legend"><div class="keys"><span class="legend-key"><i></i>NOVA Core</span><span class="legend-key"><i></i>Agent</span><span class="legend-key"><i></i>Server / Proxy</span></div><span>${state.demo?'Animierte Demo-Verbindungen':'Animation = Verbindung aktiv, keine Paketmessung'}</span></div></section>`;}

let graphNodes=[], graphEdges=[], dragging=null;
let savedPositions={};
try{savedPositions=JSON.parse(localStorage.getItem('nova-positions')||'{}');}catch{}
function graphKey(){return JSON.stringify([state.data.agents.map(a=>[a.id,a.name,a.online]),state.data.servers.map(s=>[s.id,s.name,s.agent_id,s.status])]);}
function drawGraph() {
  const svg=$('#topology');if(!svg)return;
  const d=state.data, agents=d.agents;
  const visibleServers=d.servers.length;let childIndex=0;
  graphNodes=[{id:'core',name:'NOVA Core',sub:'Control plane',kind:'core',x:150,y:170,online:true}];
  graphEdges=[];
  agents.forEach((a,i)=>{
    const children=d.servers.filter(s=>s.agent_id===a.id);
    const slot=visibleServers>1?280/(visibleServers-1):0;
    const y=children.length?(visibleServers===1?170:30+(childIndex+(children.length-1)/2)*slot):(55+i*230/Math.max(agents.length-1,1));
    graphNodes.push({id:a.id,name:a.name,sub:a.platform.split(' · ')[0]+' agent',kind:'agent',x:380,y,online:a.online});
    graphEdges.push({from:'core',to:a.id,color:'#9980e7',active:a.online});
    children.forEach((s,j)=>{
      const sy=visibleServers===1?170:30+childIndex++*slot;
      graphNodes.push({id:s.id,name:s.name,sub:s.software==='velocity'?'Velocity proxy':`Paper · ${s.metrics.players||0} Spieler`,kind:s.software==='velocity'?'proxy':'server',x:640,y:Math.max(23,Math.min(317,sy)),online:a.online&&s.status==='running'});
      graphEdges.push({from:a.id,to:s.id,color:s.software==='velocity'?'#b88ee5':'#73a6d9',active:a.online&&s.status==='running'});
    });
  });
  graphNodes=graphNodes.map(n=>({...n,...savedPositions[n.id]}));
  const paths=graphEdges.map((e,i)=>`<path id="edge-${i}" class="network-line" stroke="${e.color}"/><circle r="2.2" fill="${e.color}" class="particle" style="color:${e.color};${e.active?'':'display:none'}"><animateMotion dur="${3+(i%3)}s" repeatCount="indefinite" begin="-${i*.7}s"><mpath href="#edge-${i}"/></animateMotion></circle><circle r="1.7" fill="${e.color}" class="particle" style="${e.active?'':'display:none'}"><animateMotion dur="${4+(i%2)}s" keyPoints="1;0" keyTimes="0;1" calcMode="linear" repeatCount="indefinite" begin="-${i*.4}s"><mpath href="#edge-${i}"/></animateMotion></circle>`).join('');
  svg.innerHTML=`<defs><radialGradient id="core-glow"><stop stop-color="#8b64da" stop-opacity=".16"/><stop offset="1" stop-color="#8b64da" stop-opacity="0"/></radialGradient></defs><g id="graph-scene">${paths}${graphNodes.map(n=>`<g class="graph-node ${n.kind} ${n.online?'':'off'}" data-node="${esc(n.id)}" tabindex="0" role="button" aria-label="${esc(n.name)} öffnen"><circle r="62" fill="${n.kind==='core'?'url(#core-glow)':'none'}"/><rect class="base" x="-63" y="-24" width="126" height="48" rx="9"/><rect x="-53" y="-14" width="27" height="28" rx="6" fill="${n.kind==='core'?'#3a2b5b':n.kind==='agent'?'#2b2845':'#222e3c'}"/><svg x="-48" y="-9" width="17" height="17" class="ico node-icon"><use href="#i-${n.kind==='core'?'globe':n.kind==='agent'?'chip':n.kind==='proxy'?'network':'cube'}"/></svg><text x="-18" y="-3">${esc(n.name.length>15?n.name.slice(0,14)+'…':n.name)}</text><text class="sub" x="-18" y="10">${esc(n.sub.replace('joueurs','Spieler'))}</text><circle class="node-dot" cx="54" cy="-14" r="2.5"/></g>`).join('')}</g>`;
  state.graphSignature=graphKey();
  updateGraph();
  svg.addEventListener('pointerdown',e=>{
    const el=e.target.closest('[data-node]');if(!el)return;
    const pt=svgPoint(e,svg);const node=graphNodes.find(n=>n.id===el.dataset.node);
    dragging={node,dx:pt.x-node.x,dy:pt.y-node.y};svg.setPointerCapture(e.pointerId);
  });
  svg.addEventListener('pointermove',e=>{if(!dragging)return;const pt=svgPoint(e,svg);dragging.node.x=Math.min(730,Math.max(70,pt.x-dragging.dx));dragging.node.y=Math.min(310,Math.max(30,pt.y-dragging.dy));savedPositions[dragging.node.id]={x:dragging.node.x,y:dragging.node.y};updateGraph();});
  const endDrag=()=>{if(dragging){try{localStorage.setItem('nova-positions',JSON.stringify(savedPositions));}catch{}dragging=null;}};
  svg.addEventListener('pointerup',endDrag);svg.addEventListener('pointercancel',endDrag);
  svg.addEventListener('dblclick',e=>openNode(e.target.closest('[data-node]')?.dataset.node));
  svg.addEventListener('keydown',e=>{if(e.key==='Enter')openNode(e.target.closest('[data-node]')?.dataset.node);});
}
function svgPoint(e,svg){const p=new DOMPoint(e.clientX,e.clientY);return p.matrixTransform($('#graph-scene').getScreenCTM().inverse());}
function updateGraph(){for(const n of graphNodes){const s=server(n.id);if(s&&s.software==='paper'){n.sub=`Paper · ${s.metrics.players??'—'} Spieler`;const text=$(`[data-node="${n.id}"] text.sub`);if(text)text.textContent=n.sub;}}const scene=$('#graph-scene');if(!scene)return;scene.setAttribute('transform',`translate(${400*(1-state.zoom)} ${170*(1-state.zoom)}) scale(${state.zoom})`);graphNodes.forEach(n=>{$(`[data-node="${n.id}"]`,scene)?.setAttribute('transform',`translate(${n.x} ${n.y})`);});graphEdges.forEach((e,i)=>{const a=graphNodes.find(n=>n.id===e.from),b=graphNodes.find(n=>n.id===e.to);const dx=(b.x-a.x)*.5;$(`#edge-${i}`,scene).setAttribute('d',`M${a.x+63},${a.y} C${a.x+63+dx*.55},${a.y} ${b.x-63-dx*.55},${b.y} ${b.x-63},${b.y}`);});}
function openNode(id){if(!id)return;if(id==='core'){navigate('settings');return;}if(server(id))openDetail(id);else if(agent(id))openAgent(id);}

function chartCard(){return `<section class="card chart-card"><div class="card-head"><div><div class="card-title">Spieleraktivität</div><p class="card-subtitle">Dein Netzwerk, voller Leben.</p></div><div class="range-group">${[1,6,24].map(n=>`<button class="${state.range===n?'active':''}" data-range="${n}">${n}h</button>`).join('')}</div></div><div class="chart-value">${fmt(state.data.players)}<span>Spieler online</span></div><div id="player-chart" class="chart-wrap"></div></section>`;}
function drawChart(){const el=$('#player-chart');if(!el)return;const cutoff=Date.now()/1000-state.range*3600;let samples=state.data.samples.filter(s=>s.time>=cutoff);if(!samples.length){el.innerHTML='<div class="empty small-text">Messwerte erscheinen nach dem ersten Agenten-Heartbeat.</div>';return;}
 const values=samples.map(s=>s.players), max=Math.max(10,...values)*1.2;
 const left=30,right=740,top=15,bottom=119;
 const coords=values.map((n,i)=>[left+i*(right-left)/Math.max(values.length-1,1),bottom-(n/max)*(bottom-top)]);
 let line=coords.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
 if(coords.length===1)line+=` L${right},${coords[0][1]}`;
 const labels=Array.from({length:5},(_,i)=>{const t=Date.now()/1000-state.range*3600+(i/4)*state.range*3600;return `<text x="${left+i*(right-left)/4}" y="143" text-anchor="${i===0?'start':i===4?'end':'middle'}">${new Date(t*1000).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</text>`;}).join('');
 el.innerHTML=`<svg viewBox="0 0 765 150" preserveAspectRatio="none" role="img" aria-label="Spielerverlauf der letzten ${state.range} Stunden, ${samples.length} Messwerte"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#9c78ea" stop-opacity=".24"/><stop offset="1" stop-color="#9c78ea" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(p=>`<path d="M${left} ${bottom-p*(bottom-top)} H${right}" stroke="#283047" stroke-dasharray="3 5" stroke-width=".6"/><text x="20" y="${bottom-p*(bottom-top)+3}" text-anchor="end">${Math.round(p*max)}</text>`).join('')}<path d="${line} L${right},${bottom} L${left},${bottom}Z" fill="url(#chart-fill)"/><path d="${line}" fill="none" stroke="#a18ae6" stroke-width="2" vector-effect="non-scaling-stroke"/>${labels}</svg>`;
}
function healthCard(){const d=state.data,online=d.agents.filter(a=>a.online).length;const pct=d.agents.length?Math.round(online/d.agents.length*100):0;return `<section class="card health-card"><div class="card-head"><div class="card-title">Netzwerkstatus</div>${icon('shield')}</div><div class="health-ring"><svg viewBox="0 0 120 120"><circle cx="60" cy="60" r="47"/><circle class="progress" cx="60" cy="60" r="47" style="stroke-dashoffset:${295*(1-pct/100)}"/></svg><div class="ring-label"><strong>${pct}<span style="display:inline;font-size:15px">%</span></strong><span>Agenten erreichbar</span></div></div><div class="health-caption"><i class="dot ${pct===100?'':'off'}"></i>${!d.agents.length?'Bereit für deinen ersten Agenten':pct===100?'Alle Systeme erreichbar':'Verbindungen prüfen'}</div><div class="health-list"><div class="health-row"><span>${icon('chip')}Agenten online</span><b class="good">${online} / ${d.agents.length}</b></div><div class="health-row"><span>${icon('activity')}Fehler · letzte 24h</span><b class="${d.errors?'':'good'}">${d.errors}</b></div><div class="health-row"><span>${icon('clock')}Offene Aufträge</span><b>${d.pending}</b></div><div class="health-row"><span>${icon('shield')}Verbindung</span><b>${state.demo?'Demomodus':location.protocol==='https:'?'HTTPS':'Lokal · HTTP'}</b></div></div></section>`;}
function eventHTML(e){return `<div class="event"><span class="event-bullet ${esc(e.level)}">${icon(e.level==='error'?'close':e.level==='success'?'check':e.level==='warning'?'bell':'activity')}</span><div><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p><time>${ago(e.time)}</time></div></div>`;}
function activityCard(){return `<section class="card activity-card"><div class="card-head"><div class="card-title">Letzte Aktivitäten</div><span class="dot"></span></div><div class="activity-list">${state.data.events.slice(0,3).map(eventHTML).join('')||'<div class="empty">Hier beginnt deine Geschichte.</div>'}</div><div class="activity-footer"><button data-nav="activity">Alle Aktivitäten ansehen ${icon('arrow')}</button></div></section>`;}

function serverTable(all=false){const servers=state.data.servers;return `<section class="card servers-card"><div class="card-head"><div><div class="card-title">Deine Instanzen <span class="pill muted">${servers.length}</span></div><p class="card-subtitle">Große Abenteuer beginnen mit einem Server.</p></div>${!all?`<button class="button ghost small" data-nav="servers">Alle verwalten ${icon('arrow')}</button>`:createButton}</div>${servers.length?`<div class="table-scroll"><table><thead><tr><th>INSTANZ</th><th>STATUS</th><th>AGENT</th><th>SPIELER</th><th>CPU</th><th>RAM</th><th aria-label="Aktionen"></th></tr></thead><tbody>${servers.map(s=>`<tr><td><button class="server-name" data-server="${s.id}"><span class="server-art ${s.software}">${icon(s.software==='velocity'?'network':'cube')}</span><span><strong>${esc(s.name)}</strong><small>${s.software==='velocity'?'Velocity':'Paper'} ${esc(s.version)}</small></span></button></td><td>${statusBadge(s)}</td><td><span class="table-bar"><i class="dot ${agent(s.agent_id)?.online?'':'off'}" style="width:4px;height:4px"></i>${esc(agent(s.agent_id)?.name||'—')}</span></td><td>${s.status==='running'?fmt(s.metrics.players):'—'} <span style="color:#56637c">${s.status==='running'?'/ '+(s.metrics.max_players||'—'):''}</span></td><td><span class="table-bar">${s.status==='running'?fmt(s.metrics.cpu)+'%':'—'}<i style="--value:${Math.min(100,s.metrics.cpu||0)}%"></i></span></td><td>${s.status==='running'?fmt(s.metrics.ram)+' GB':'—'}</td><td><div class="table-actions"><button class="icon-btn" data-server="${s.id}" data-tab="console" title="Konsole öffnen">${icon('terminal')}</button><button class="icon-btn" data-server="${s.id}" title="Instanz öffnen">${icon('chevron')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Dein erstes Abenteuer wartet.','Verbinde einen Agenten und installiere deinen ersten Minecraft-Server.',state.data.agents.length?createButton:pairButton)}</section>`;}

function renderView() {
 if(!state.data)return;
 state.graphSignature='';
 const d=state.data;
 $('#crumb').textContent=names[state.view];
 $$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.nav===state.view));
 $('[data-count="servers"]').textContent=d.servers.length;$('[data-count="agents"]').textContent=d.agents.length;
 const content=$('#content');
 switch(state.view){
  case 'dashboard':content.innerHTML=title('Dein Netzwerk. Alle Welten im Blick.',`Schön, dass du da bist. <span>Dein nächstes Abenteuer beginnt hier.</span>`,pairButton+createButton)+`<div id="dashboard-stats">${stats()}</div><div class="dashboard-grid"><div>${graphCard()}${chartCard()}<div id="dashboard-servers">${serverTable()}</div></div><aside class="dashboard-side">${healthCard()}${activityCard()}</aside></div>`+footer();drawGraph();drawChart();break;
  case 'network':content.innerHTML=title('Ein Netzwerk. Unendliche Welten.','Ziehe deine Nodes, erkunde Verbindungen und verknüpfe dein Netzwerk.',`<button class="button" data-action="sync">${icon('network')}Netzwerk verknüpfen</button>`+createButton)+`<div class="info-strip">${icon('shield')}Verknüpfen richtet Velocity Modern Forwarding ein. Alle Instanzen müssen gestoppt sein. Backend-Ports per Firewall ausschließlich für den Proxy öffnen.</div>`+graphCard(true)+serverTable()+footer();drawGraph();break;
  case 'servers':content.innerHTML=title('Deine Welten. Deine Regeln.','Paper-Server und Velocity-Proxys. Von hier aus unter Kontrolle.',pairButton+createButton)+stats()+serverTable(true)+footer();break;
  case 'agents':content.innerHTML=title('Die Kraft hinter deinem Netzwerk.','Linux, Windows oder Raspberry Pi. Ein Agent verbindet sie alle.',pairButton)+`<div class="agent-grid">${d.agents.map(a=>`<section class="card agent-card"><div class="agent-card-top"><span class="stat-icon">${icon('chip')}</span><span class="pill ${a.online?'':'muted'}"><i class="dot ${a.online?'':'off'}"></i>${a.online?'Verbunden':'Offline'}</span></div><h3>${esc(a.name)}</h3><p>${esc(a.platform)} <span>· ${esc(a.address)}</span></p><div class="agent-resource"><div class="resource-label"><span>CPU-Auslastung</span><span>${a.online?fmt(a.metrics.cpu)+'%':'—'}</span></div><div class="bar"><span style="width:${a.online?Math.min(a.metrics.cpu||0,100):0}%"></span></div></div><div class="agent-resource"><div class="resource-label"><span>Arbeitsspeicher</span><span>${a.online?fmt(a.metrics.ram_used)+' / '+fmt(a.metrics.ram_total)+' GB':'—'}</span></div><div class="bar"><span style="width:${a.online?Math.min((a.metrics.ram_used||0)/(a.metrics.ram_total||1)*100,100):0}%"></span></div></div><div class="agent-footer"><span class="small-text">${d.servers.filter(s=>s.agent_id===a.id).length} Instanzen</span><button class="button small" data-agent="${a.id}">Details ${icon('arrow')}</button></div></section>`).join('')}</div>${!d.agents.length?`<section class="card">${empty('Mehr Power für deine Welten.','Verbinde deinen ersten Rechner. Der Agent benötigt keinen eingehenden Verwaltungsport.',pairButton)}</section>`:''}`+footer();break;
  case 'routines':content.innerHTML=title('Lass dein Netzwerk für dich arbeiten.','Wiederkehrende Aktionen. Weniger Klicks, mehr Zeit fürs Spielen.',`<button class="button primary" data-action="routine">${icon('plus')}Routine erstellen</button>`)+`<div class="info-strip">${icon('clock')}Routinen werden von der laufenden Zentrale ausgelöst. Backups benötigen gestoppte Instanzen; Offline-Agenten werden im Aktivitätsprotokoll gemeldet.</div><div class="routine-list">${d.routines.map(r=>`<section class="card routine-card"><span class="stat-icon">${icon(r.action==='backup'?'folder':'clock')}</span><div><h3>${esc(r.name)}</h3><p>${esc(server(r.server_id)?.name||'—')} · ${actionLabel(r.action)} · alle ${fmt(r.interval_minutes)} Minuten</p></div><div class="routine-next">${date(r.next_run)}<small>Nächste Ausführung</small></div><span class="pill">Aktiv</span><button class="icon-btn" data-delete-routine="${r.id}" title="Routine entfernen">${icon('trash')}</button></section>`).join('')||`<section class="card">${empty('Dein Netzwerk im Autopilot.','Plane Starts, Stopps, Neustarts und Backups für deine Instanzen.',`<button class="button primary" data-action="routine">${icon('plus')}Erste Routine erstellen</button>`)}</section>`}</div>`+footer();break;
  case 'activity':content.innerHTML=title('Alles, was in deinem Universum passiert.','Installationen, Routinen und Ereignisse. An einem Ort.',`<button class="button" data-action="refresh">${icon('refresh')}Aktualisieren</button>`)+`<section class="card"><div class="card-head"><div class="card-title">Aktivitätsprotokoll</div><span class="pill muted">Letzte ${d.events.length} Ereignisse</span></div><div class="activity-list">${d.events.map(eventHTML).join('')||empty('Noch ganz ruhig hier.','Deine Netzwerkaktivitäten erscheinen automatisch hier.')}</div></section>`+footer();break;
  case 'settings':content.innerHTML=title('Deine Zentrale. Dein Stil.','Ein Zuhause für dein Minecraft-Netzwerk.')+`<div class="settings-grid"><section class="card settings-card"><h3>Erscheinungsbild</h3><p>Midnight Violet. Gemacht für lange Nächte und große Ideen.</p><label class="settings-row"><span>Bewegung & Datenströme<small>Animationen in deiner Netzwerkkarte aktivieren</small></span><input id="motion-toggle" class="switch" type="checkbox" ${document.body.classList.contains('no-motion')?'':'checked'}></label><div class="settings-row"><span>Node-Anordnung<small>Positionen werden in diesem Browser gespeichert</small></span><button class="button small" data-action="reset-graph">Zurücksetzen</button></div></section><section class="card settings-card"><h3>Verbindung & Sicherheit</h3><div class="settings-row"><span>Betriebsmodus</span><span class="pill ${state.demo?'purple':''}">${state.demo?'Isolierte Demo':'Zentrale'}</span></div><div class="settings-row"><span>Transport</span><span>${location.protocol==='https:'?'HTTPS':'HTTP · nur vertrauenswürdiges Netz'}</span></div><div class="settings-row"><span>Admin-Passwort<small>Lokal mit „python -m nova password“ ändern</small></span>${icon('shield')}</div><p>${state.demo?'Demoaktionen verändern keine echten Minecraft-Server. Für echte Agenten NOVA ohne --demo starten.':'Extern ausschließlich hinter einem HTTPS-Reverse-Proxy betreiben. Agenten speichern ihre Schlüssel lokal; Einmalcodes laufen nach 10 Minuten ab.'}</p></section><section class="card settings-card"><h3>Made for your next world.</h3><p>NOVA v0.1.0 · Python · FastAPI · SQLite<br>Keine Node.js-Laufzeit. Kein Frontend-Build. Nur dein Netzwerk und du.</p><button class="button" data-action="guide">${icon('book')}Schnellstart öffnen</button></section></div>`+footer();$('#motion-toggle').onchange=e=>{document.body.classList.toggle('no-motion',!e.target.checked);localStorage.setItem('nova-motion',String(e.target.checked));};break;
 }
}
function actionLabel(a){return {start:'Starten',stop:'Stoppen',restart:'Neustarten',backup:'Backup'}[a]||a;}
function navigate(view){if(!names[view])view='dashboard';state.view=view;location.hash=view;$('.sidebar')?.classList.remove('open');renderView();}
function updateDashboard(){const d=state.data;$('[data-count="servers"]').textContent=d.servers.length;$('[data-count="agents"]').textContent=d.agents.length;$('#dashboard-stats').innerHTML=stats();$('#dashboard-servers').innerHTML=serverTable();$('.health-card').outerHTML=healthCard();$('.activity-card').outerHTML=activityCard();$('.chart-value').innerHTML=`${fmt(d.players)}<span>Spieler online</span>`;drawChart();if(graphKey()!==state.graphSignature)drawGraph();else updateGraph();}
async function refresh(render=true){if(state.loading)return;state.loading=true;try{state.data=await api('/overview');if(render&&!state.modal&&!dragging&&!$('#confirm-dialog').open){if(state.view==='dashboard'&&$('#dashboard-stats'))updateDashboard();else if(render===true||!$('#content').contains(document.activeElement))renderView();}}finally{state.loading=false;}}

let previousFocus=null, modalTimer=null;
function modal(title_, subtitle, content, footer_='', wide=false){
 previousFocus=document.activeElement;
 state.modal=true;clearInterval(modalTimer);
 $('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header class="modal-header"><div><h2 id="modal-title">${title_}</h2><p>${subtitle}</p></div><button class="icon-btn" data-action="close" aria-label="Schließen">${icon('close')}</button></header>${content}${footer_?`<footer class="modal-footer">${footer_}</footer>`:''}</section></div>`;
 setTimeout(()=>{const focus=$('[autofocus]',$('#modal-root'))||$('.modal');focus?.focus();},0);
}
async function closeModal(force=false){if(state.dirty&&!force&&!await confirmAction('Ungespeicherte Änderungen','Editor wirklich schließen? Deine Änderungen gehen verloren.','Verwerfen'))return false;state.modal=null;state.dirty=false;clearInterval(modalTimer);$('#modal-root').innerHTML='';previousFocus?.focus();return true;}
function formError(form,error){let el=$('.form-error',form);if(!el){el=document.createElement('div');el.className='form-error';form.prepend(el);}el.textContent=error;}
async function confirmAction(heading,text,yes='Bestätigen'){const dialog=$('#confirm-dialog');if(dialog.open)return false;dialog.innerHTML=`<h3>${esc(heading)}</h3><p>${esc(text)}</p><form method="dialog" class="page-actions"><button class="button" value="cancel">Abbrechen</button><button class="button danger" value="yes">${esc(yes)}</button></form>`;dialog.showModal();return new Promise(resolve=>dialog.addEventListener('close',()=>resolve(dialog.returnValue==='yes'),{once:true}));}

async function openCreate() {
 if(!state.data.agents.length){openPair();return;}
 state.software='paper';
 modal('Eine neue Welt beginnt.','Installiere einen Minecraft-Server oder Proxy auf einem Agenten.',`<form id="create-form"><div class="modal-body">${state.demo?'<div class="info-strip">Demomodus: Es werden keine JAR-Dateien heruntergeladen.</div>':''}<div class="software-picker"><button type="button" class="software-option selected" data-software="paper">${icon('cube')}<span><strong>Paper</strong><small>Minecraft-Server</small></span></button><button type="button" class="software-option" data-software="velocity">${icon('network')}<span><strong>Velocity</strong><small>Netzwerk-Proxy</small></span></button></div><label class="form-field"><span>Instanzname</span><input name="name" required pattern="[a-zA-Z0-9_-]+" maxlength="32" placeholder="z. B. Survival" autofocus><small>Buchstaben, Zahlen, Unterstrich oder Bindestrich. Netzwerkweit eindeutig.</small></label><div class="form-grid"><label class="form-field"><span>Agent</span><select name="agent_id">${state.data.agents.filter(a=>a.online).map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(a.platform.split(' · ')[0])}</option>`).join('')}</select></label><label class="form-field"><span>Version</span><select name="version" id="version-select" required><option value="">Wird geladen …</option></select></label></div><div class="form-grid"><label class="form-field"><span>Port</span><input name="port" type="number" value="25565" min="1024" max="65535" required></label><label class="form-field"><span>RAM (MB)</span><input name="memory" type="number" value="2048" min="512" max="65536" step="256" required></label></div><label class="check-row" id="eula-row"><input type="checkbox" name="accept_eula" required><span>Ich akzeptiere die <a href="https://www.minecraft.net/eula" target="_blank" rel="noopener">Minecraft-EULA</a> und habe die Nutzungsrechte für diesen Server.</span></label><p class="small-text">Der Agent benötigt Java 21+. Neueste Versionen können Java 25 voraussetzen. Downloads werden mit SHA-256 geprüft.</p></div><div class="modal-footer"><button type="button" class="button" data-action="close">Abbrechen</button><button type="submit" class="button primary">${icon('plus')}Instanz installieren</button></div></form>`);
 $('#create-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=$('[type="submit"]',form);button.disabled=true;const fd=new FormData(form);try{const result=await api('/servers','POST',{name:fd.get('name'),agent_id:fd.get('agent_id'),software:state.software,version:fd.get('version'),port:Number(fd.get('port')),memory:Number(fd.get('memory')),accept_eula:fd.has('accept_eula')});await refresh(false);await closeModal(true);toast('Installation wurde beauftragt. Fortschritt im Serverstatus.');navigate('servers');openDetail(result.server_id);}catch(err){formError($('.modal-body',form),err.message);button.disabled=false;}};
 await loadVersions('paper');
}
async function loadVersions(software){const select=$('#version-select');if(!select)return;select.innerHTML='<option value="">Wird geladen …</option>';try{const d=await api('/catalog/'+software);if(state.software!==software||!select.isConnected)return;select.innerHTML=d.versions.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');}catch(err){if(select.isConnected){select.innerHTML='<option value="">Katalog nicht erreichbar</option>';formError($('.modal-body'),err.message);}}}

async function openPair(){
 modal('Mehr Power für dein Netzwerk.','Verbinde einen Linux-, Windows- oder Raspberry-Pi-Agenten.',`<div class="modal-body"><div class="info-strip">${icon('shield')}${state.demo?'Demomodus: Kopplung ist erst im Echtbetrieb möglich.':'Einmalcode · 10 Minuten gültig · nur einmal verwendbar'}</div><div class="steps"><div class="step"><h3>NOVA auf den Zielrechner holen</h3><p>Python 3.11+ und Java 21+ installieren. Repository klonen oder als ZIP entpacken.</p><pre class="code-block">git clone https://github.com/NikiM2009/NOVA.git
cd NOVA</pre></div><div class="step"><h3>Agent installieren und starten</h3><p>Auf Windows gegebenenfalls „py“ statt „python“ verwenden. Die Zentrale muss vom Agenten per HTTPS erreichbar sein.</p><pre class="code-block" id="agent-command"></pre><p>Der Agent fragt nach dem Code. Er wird nicht als Kommandozeilenargument gespeichert.</p></div><div class="step"><h3>Kopplungscode einfügen</h3><div class="token-line"><pre class="code-block" id="pair-token">Code wird erstellt …</pre><button class="icon-btn" data-action="copy-token" title="Code kopieren">${icon('copy')}</button></div><p>Danach erscheint die Maschine automatisch unter Agenten. Für Proxy-Routen muss ihre Adresse von den anderen Maschinen erreichbar sein (siehe Dokumentation).</p></div></div></div>`,`<button class="button primary" data-action="pair-done">${icon('check')}Verstanden</button>`);
 $('#agent-command').textContent=`python install.py --agent --url ${location.origin}`;
 try{const result=await api('/pairing','POST');if($('#pair-token'))$('#pair-token').textContent=result.token;}catch(err){toast(err.message,true);}
}

function openAgent(id){const a=agent(id);modal(esc(a.name),'Agent · '+esc(a.platform),`<div class="modal-body"><div class="detail-overview"><div class="detail-metric">CPU<strong>${a.online?fmt(a.metrics.cpu):'—'} <small>%</small></strong></div><div class="detail-metric">RAM<strong>${a.online?fmt(a.metrics.ram_used):'—'} <small>GB</small></strong></div><div class="detail-metric">Speicher belegt<strong>${a.online?fmt(a.metrics.disk):'—'} <small>%</small></strong></div></div><div class="detail-info"><span>Status <b>${a.online?'Verbunden':'Offline'}</b></span><span>Adresse <b>${esc(a.address)}</b></span><span>Letzter Kontakt <b>${state.demo?'Demo':ago(a.last_seen)}</b></span><span>Instanzen <b>${state.data.servers.filter(s=>s.agent_id===id).length}</b></span><span>Datenverzeichnis <b>${esc(a.metrics.data_dir||'Noch nicht gemeldet')}</b></span></div><p class="notice">Die Adresse muss vom Proxy aus erreichbar sein. Sie wird beim Koppeln mit --address festgelegt. Agent unter einem eigenen Betriebssystemkonto ausführen; Netzwerkfreigaben bleiben unter deiner Kontrolle.</p></div>`,`<button class="button danger" data-revoke-agent="${id}">${icon('trash')}Agent entfernen</button><button class="button" data-action="close">Schließen</button>`,true);}

function openRoutine(){if(!state.data.servers.length){toast('Erstelle zuerst eine Instanz.',true);return;}modal('Mehr Zeit für deine Welten.','Eine wiederkehrende Aktion einrichten.',`<form id="routine-form"><div class="modal-body"><label class="form-field"><span>Name</span><input name="name" required maxlength="60" placeholder="z. B. Nächtlicher Neustart" autofocus></label><label class="form-field"><span>Instanz</span><select name="server_id">${state.data.servers.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><div class="form-grid"><label class="form-field"><span>Aktion</span><select name="action"><option value="restart">Neustarten</option><option value="start">Starten</option><option value="stop">Stoppen</option><option value="backup">Backup (gestoppt)</option></select></label><label class="form-field"><span>Intervall in Minuten</span><input name="interval_minutes" type="number" min="5" max="525600" value="1440" required></label></div><div class="notice">Erster Lauf nach Ablauf des Intervalls. Die Zentrale und der Agent müssen laufen. Backups werden nur bei gestoppten Instanzen erstellt.</div></div><div class="modal-footer"><button type="button" class="button" data-action="close">Abbrechen</button><button type="submit" class="button primary">Routine erstellen</button></div></form>`);$('#routine-form').onsubmit=async e=>{e.preventDefault();const button=$('[type="submit"]',e.target);button.disabled=true;const fd=new FormData(e.target);try{await api('/routines','POST',{name:fd.get('name'),server_id:fd.get('server_id'),action:fd.get('action'),interval_minutes:Number(fd.get('interval_minutes'))});await closeModal(true);await refresh();navigate('routines');toast('Routine gespeichert.');}catch(err){formError($('.modal-body'),err.message);button.disabled=false;}};}

function openDetail(id,tab='overview') {
 const s=server(id);if(!s)return;
 state.serverId=id;state.detailTab=tab;state.filePath='';state.editorPath=null;state.dirty=false;
 modal(esc(s.name),`${s.software==='velocity'?'Velocity Proxy':'Paper Minecraft'} · ${esc(s.version)} · ${esc(agent(s.agent_id)?.name||'—')}`,`<div class="detail-tabs">${[['overview','Übersicht'],['console','Konsole'],['files','Dateien'],['manage','Verwalten']].map(([key,label])=>`<button class="${tab===key?'active':''}" data-detail-tab="${key}">${label}</button>`).join('')}</div><div class="modal-body" id="detail-body"></div>`,'',true);
 renderDetail();
 modalTimer=setInterval(async()=>{if(!state.modal||!state.serverId)return;try{await refresh(false);if(state.detailTab==='overview')renderDetail();if(state.detailTab==='console'&&!state.logLoading)loadLogs();}catch{}},6000);
}
function renderDetail(){
 const s=server(state.serverId);if(!s||!$('#detail-body'))return;
 $$('.detail-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.detailTab===state.detailTab));
 const body=$('#detail-body');
 const setup=s.installation;
 const needsInstall=s.status==='missing'||setup?.status==='failed';
 const blocked=needsInstall||s.status==='installing';
 if(state.detailTab==='overview'){
  body.innerHTML=`${state.demo?'<div class="info-strip">Demoinstanz · Aktionen und Konsolenausgaben sind simuliert.</div>':''}<div class="page-actions" style="margin-bottom:20px">${statusBadge(s)}<span style="flex:1"></span><button class="button primary" data-power="start" ${blocked?'disabled':''}>${icon('play')}Starten</button><button class="button" data-power="restart" ${blocked?'disabled':''}>${icon('refresh')}Neustart</button><button class="button danger" data-power="stop" ${blocked?'disabled':''}>${icon('stop')}Stoppen</button></div>${needsInstall?`<div class="form-error"><strong>${s.status==='missing'?'Instanz fehlt im Agentenverzeichnis':'Installation fehlgeschlagen'}</strong><p>${esc(setup?.error||'Der Agent kennt diese Instanz lokal nicht. Prüfe, ob er mit dem richtigen --data-Verzeichnis läuft.')}</p><p>Agenten-Datenverzeichnis: ${esc(agent(s.agent_id)?.metrics.data_dir||'Noch nicht gemeldet; Agent aktualisieren und neu starten.')}</p><button class="button" data-action="retry-install">${icon('refresh')}Installation wiederholen</button></div>`:''}<div class="detail-overview"><div class="detail-metric">Spieler<strong>${s.status==='running'?fmt(s.metrics.players):'—'} <small>/ ${s.metrics.max_players||'—'}</small></strong></div><div class="detail-metric">CPU-Auslastung<strong>${s.status==='running'?fmt(s.metrics.cpu):'—'} <small>%</small></strong></div><div class="detail-metric">RAM-Nutzung<strong>${s.status==='running'?fmt(s.metrics.ram):'—'} <small>GB</small></strong></div></div><div class="detail-info"><span>Software <b>${esc(s.software)} ${esc(s.version)}</b></span><span>Agent <b>${esc(agent(s.agent_id)?.name||'—')}</b></span><span>Port <b>${s.port}</b></span><span>RAM-Limit <b>${s.memory} MB</b></span><span>Adresse <b>${esc(agent(s.agent_id)?.address||'—')}:${s.port}</b></span><span>Instanz-ID <b>${esc(s.id)}</b></span></div><div class="notice">${s.status==='installing'?'Der Agent lädt die ausgewählte Version herunter und prüft den SHA-256-Hash. Fehler erscheinen in den Aktivitäten.':s.software==='velocity'?'Dein Einstiegspunkt ins Netzwerk. Unter „Netzwerk → Netzwerk verknüpfen“ werden Paper-Server und Modern Forwarding eingerichtet.':'Konfigurationen direkt unter Dateien bearbeiten. Eine laufende JVM bedeutet noch nicht, dass Minecraft bereits Verbindungen annimmt.'}</div>`;
 } else if(state.detailTab==='console'){
  body.innerHTML=`<div class="file-toolbar"><span class="small-text">${icon('terminal')} Java-Konsole · letzte 400 Zeilen</span><button class="button small" style="margin-left:auto" data-action="logs">${icon('refresh')}Aktualisieren</button></div><div class="console" id="console-output" role="log">Konsole wird geladen …</div><form id="command-form" class="command-form"><input class="input" name="command" aria-label="Konsolenbefehl" maxlength="1000" placeholder="Befehl eingeben, z. B. list oder say Hallo!" required autocomplete="off"><button class="button primary" type="submit">Senden ${icon('arrow')}</button></form>`;
  $('#command-form').onsubmit=async e=>{e.preventDefault();const input=e.target.command,button=$('button',e.target);button.disabled=true;try{await job(api(`/servers/${s.id}/command`,'POST',{command:input.value}));input.value='';toast('Befehl gesendet.');await loadLogs();}catch(err){toast(err.message,true);}finally{button.disabled=false;}};
  loadLogs();
 } else if(state.detailTab==='files'){loadFiles();}
 else if(state.detailTab==='manage'){
  body.innerHTML=`<div class="settings-row"><span>Backup erstellen<small>ZIP-Archiv ohne server.jar, nur bei gestoppter Instanz.<br>Liegt auf dem Agenten unter backups/${esc(s.id)}/.</small></span><button class="button" data-power="backup">${icon('folder')}Backup</button></div><div class="settings-row"><span>Instanz aus NOVA entfernen<small>Zuerst stoppen. Dateien auf dem Agenten bleiben erhalten.<br>Backups und verwaiste Instanzdateien bei Bedarf lokal verwalten.</small></span><button class="button danger" data-action="delete-server">${icon('trash')}Entfernen</button></div><p class="notice">Version, Java-Laufzeit und RAM-Limit sind für diese Instanz festgelegt. Für einen Versionswechsel eine neue Instanz erstellen und kompatible Welt-/Konfigurationsdateien übertragen. Vorher immer ein Backup anlegen.</p>`;
 }
}
async function loadLogs(){if(state.logLoading||!$('#console-output'))return;state.logLoading=true;const id=state.serverId;try{const d=await job(api(`/servers/${id}/logs`),18000);const out=$('#console-output');if(out&&state.serverId===id){out.innerHTML=d.lines.map(l=>`<div class="console-line">${esc(l)}</div>`).join('');out.scrollTop=out.scrollHeight;}}catch(err){if($('#console-output'))$('#console-output').textContent=err.message;}finally{state.logLoading=false;}}

async function loadFiles(path=state.filePath){
 const body=$('#detail-body');if(!body)return;
 state.filePath=path;state.editorPath=null;state.dirty=false;
 const id=state.serverId;
 body.innerHTML='<div class="empty">Verzeichnis wird geladen …</div>';
 try{const result=await job(api(`/servers/${id}/files/list`,'POST',{path}),20000);if(!state.modal||state.detailTab!=='files'||id!==state.serverId)return;
 body.innerHTML=`<div class="file-toolbar"><button class="icon-btn" data-action="file-up" title="Übergeordnetes Verzeichnis">${icon('arrow')}</button><span class="file-path">/${esc(path)}</span><button class="button small" data-new-file="write">${icon('plus')}Datei</button><button class="button small" data-new-file="mkdir">${icon('folder')}Ordner</button><button class="button small" data-action="upload">${icon('upload')}Upload</button><input id="upload-file" type="file" hidden></div><div id="file-create"></div><div class="file-list">${result.entries.map(f=>`<div class="file-item">${icon(f.directory?'folder':'file')}<button class="file-open" data-file="${esc(f.name)}" data-is-dir="${f.directory}">${esc(f.name)}</button><small>${f.directory?'Ordner':bytes(f.size)}</small><button class="icon-btn" title="Löschen" data-delete-file="${esc(f.name)}">${icon('trash')}</button></div>`).join('')||'<div class="empty">Noch keine Dateien in diesem Verzeichnis.</div>'}</div><p class="small-text">UTF-8-Editor und Upload bis 1 MB · Ordner nur leer löschbar · keine Symlinks</p>`;
 $('#upload-file').onchange=uploadFile;
 }catch(err){if(body.isConnected){body.innerHTML=`<div class="form-error">${esc(err.message)}</div><button class="button" data-action="reload-files">Erneut versuchen</button>`;}}
}
async function openFile(name,isDir){if(state.dirty&&!await confirmAction('Änderungen verwerfen?','Die Datei enthält ungespeicherte Änderungen.','Verwerfen'))return;const path=[state.filePath,name].filter(Boolean).join('/');if(isDir){loadFiles(path);return;}const id=state.serverId;try{const data=await job(api(`/servers/${id}/files/read`,'POST',{path}),20000);if(id!==state.serverId||state.detailTab!=='files'||!state.modal)return;state.editorPath=path;state.dirty=false;$('#detail-body').innerHTML=`<div class="editor-title"><button class="button small" data-action="editor-back">${icon('folder')}Dateien</button><span class="small-text">${esc(path)}</span><button class="button primary small" data-action="save-file">${icon('check')}Speichern</button></div><textarea class="editor" id="file-editor" aria-label="Dateiinhalt von ${esc(path)}" spellcheck="false"></textarea><p id="editor-status" class="small-text">UTF-8 · Änderungen werden erst beim Speichern übertragen.</p>`;$('#file-editor').value=data.content;$('#file-editor').oninput=()=>{state.dirty=true;$('#editor-status').textContent='Ungespeicherte Änderungen';};}catch(err){toast(err.message,true);}}
function newFileForm(operation){$('#file-create').innerHTML=`<form id="new-file-form" class="inline-form"><input class="input" name="name" required aria-label="Name" placeholder="${operation==='mkdir'?'Ordnername':'Dateiname, z. B. notes.txt'}" pattern="[^/\\\\]+" maxlength="100"><button class="button primary small" type="submit">Erstellen</button><button class="icon-btn" data-action="cancel-new-file" type="button" aria-label="Abbrechen">${icon('close')}</button></form>`;$('#new-file-form input').focus();$('#new-file-form').onsubmit=async e=>{e.preventDefault();const name=new FormData(e.target).get('name');if(['.','..'].includes(name)||name.includes(':')){toast('Ungültiger Name',true);return;}const path=[state.filePath,name].filter(Boolean).join('/');try{await job(api(`/servers/${state.serverId}/files/${operation}`,'POST',{path,content:'',overwrite:false}),20000);toast(operation==='mkdir'?'Ordner erstellt.':'Datei erstellt.');await loadFiles();}catch(err){toast(err.message,true);}};}
async function uploadFile(e){const file=e.target.files[0];if(!file)return;if(file.size>1_000_000){toast('Upload-Limit: 1 MB. Große JARs lokal auf dem Agenten ablegen.',true);return;}const path=[state.filePath,file.name].filter(Boolean).join('/');if(!await confirmAction('Datei hochladen',`${file.name} (${bytes(file.size)}) hochladen? Eine vorhandene Datei gleichen Namens wird ersetzt.`,'Hochladen'))return;try{const buffer=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<buffer.length;i+=8192)binary+=String.fromCharCode(...buffer.subarray(i,i+8192));await job(api(`/servers/${state.serverId}/files/write`,'POST',{path,content:btoa(binary),encoding:'base64'}),30000);toast('Upload abgeschlossen.');loadFiles();}catch(err){toast(err.message,true);}}

function openSearch(){modal('Finde deine nächste Welt.','Server, Proxys und Agenten durchsuchen.',`<div class="modal-body"><input class="input" id="global-search" autofocus placeholder="Name, Software oder Adresse …" aria-label="Netzwerk durchsuchen"><div id="search-results" class="search-results"></div></div>`);const search=()=>{const q=$('#global-search').value.toLowerCase();const results=[...state.data.servers.map(s=>({id:s.id,title:s.name,sub:s.software+' '+s.version,type:'server',icon:'cube'})),...state.data.agents.map(a=>({id:a.id,title:a.name,sub:a.address,type:'agent',icon:'chip'}))].filter(x=>(x.title+' '+x.sub).toLowerCase().includes(q));$('#search-results').innerHTML=results.map(x=>`<button class="search-result" ${x.type==='server'?'data-server':'data-agent'}="${x.id}">${icon(x.icon)}<span><strong>${esc(x.title)}</strong><small>${esc(x.sub)}</small></span></button>`).join('')||'<div class="empty">Keine Ergebnisse gefunden.</div>';};$('#global-search').oninput=search;search();}
function openGuide(){modal('Willkommen in deinem Universum.','NOVA Schnellstart · Python 3.11+ · kein Node.js',`<div class="modal-body guide"><h3>01 · Zentrale starten</h3><pre class="code-block">python install.py</pre><p>Im NOVA-Verzeichnis ausführen. Der Installer legt eine virtuelle Python-Umgebung an, installiert NOVA und startet die Zentrale. Beim ersten Start wird ein Admin-Passwort im Terminal angezeigt. Für die Demo: <code>python install.py --demo</code>.</p><h3>02 · Agenten verbinden</h3><p>Unter Agenten einen Einmalcode erstellen. Auf dem Zielgerät NOVA installieren und den Agenten starten:</p><pre class="code-block">python install.py --agent --url https://nova.example.com</pre><p>Mit <code>.venv/bin/python -m nova agent --url … --address 10.0.0.11</code> eine vom Proxy erreichbare Adresse festlegen. Unter Windows: <code>.venv\Scripts\python.exe</code>. Raspberry Pi: 64-Bit-OS und passendes Java 21+.</p><h3>03 · Deine Welten erstellen</h3><ol><li>Velocity als Einstiegspunkt und mindestens einen Paper-Server installieren.</li><li>Version, Port und RAM wählen; für Paper die Minecraft-EULA akzeptieren.</li><li>Vor dem Verknüpfen alle Instanzen stoppen. „Netzwerk verknüpfen“ sichert und schreibt die Forwarding-Konfigurationen.</li><li>Die Paper-Ports per Firewall ausschließlich für den Proxy erreichbar machen. Nur den Velocity-Spielport öffentlich freigeben.</li><li>Zuerst Paper-Server, dann Velocity starten. Konsolen und Spielerverbindungen prüfen.</li></ol><h3>04 · Sicher betreiben</h3><p>Zentrale extern hinter HTTPS betreiben. Agent als dedizierten Benutzer ausführen. Backups benötigen gestoppte Instanzen und liegen lokal auf dem Agenten. Für einen dauerhaften Betrieb die dokumentierten systemd-/Windows-Aufgabenplaner-Beispiele im Repository verwenden.</p><h3>Demo und echte Welt</h3><p>Die Demo hat eine eigene Datenbank, simulierte Metriken und lokale Beispieldateien. Sie kann keine echten Agenten koppeln und lädt keine Server herunter. Zum Wechseln NOVA ohne <code>--demo</code> starten.</p></div>`,`<button class="button primary" data-action="close">Los geht’s ${icon('arrow')}</button>`,true);}

document.addEventListener('click',async e=>{
 const el=e.target.closest('button,a');if(!el||el.disabled)return;
 try{
  if(el.dataset.nav){navigate(el.dataset.nav);return;}
  if(el.dataset.server){if(state.dirty&&!await confirmAction('Änderungen verwerfen?','Nicht gespeicherte Dateiänderungen gehen verloren.','Verwerfen'))return;openDetail(el.dataset.server,el.dataset.tab||'overview');return;}
  if(el.dataset.agent){openAgent(el.dataset.agent);return;}
  if(el.dataset.range){state.range=Number(el.dataset.range);$$('[data-range]').forEach(b=>b.classList.toggle('active',b===el));drawChart();return;}
  if(el.dataset.software){state.software=el.dataset.software;$$('[data-software]').forEach(b=>b.classList.toggle('selected',b===el));$('#create-form').port.value=state.software==='velocity'?25565:25566;$('#create-form').memory.value=state.software==='velocity'?1024:2048;$('#eula-row').hidden=state.software==='velocity';$('#create-form').accept_eula.required=state.software==='paper';await loadVersions(state.software);return;}
  if(el.dataset.detailTab){if(state.dirty&&!await confirmAction('Änderungen verwerfen?','Ungespeicherte Dateiänderungen gehen verloren.','Verwerfen'))return;state.dirty=false;state.detailTab=el.dataset.detailTab;renderDetail();return;}
  if(el.dataset.power){const action=el.dataset.power,id=state.serverId;if(['stop','restart'].includes(action)&&!await confirmAction(actionLabel(action),`„${server(id).name}“ ${action==='stop'?'stoppen':'neu starten'}? Verbundene Spieler werden getrennt.`,actionLabel(action)))return;el.disabled=true;try{toast(actionLabel(action)+' angefordert …');const result=await job(api(`/servers/${id}/actions/${action}`,'POST'),180000);toast(result.message||'Auftrag abgeschlossen.');await refresh(false);if(state.serverId===id&&state.detailTab==='overview')renderDetail();}finally{el.disabled=false;}return;}
  if(el.dataset.deleteRoutine){if(await confirmAction('Routine entfernen','Diese Routine wird nicht mehr ausgeführt.','Entfernen')){await api('/routines/'+el.dataset.deleteRoutine,'DELETE');await refresh();toast('Routine entfernt.');}return;}
  if(el.dataset.revokeAgent){if(await confirmAction('Agent entfernen','Der Zugriffsschlüssel wird widerrufen. Zuerst alle Instanzen entfernen.','Entfernen')){await api('/agents/'+el.dataset.revokeAgent,'DELETE');await closeModal(true);await refresh();toast('Agent entfernt.');}return;}
  if(el.dataset.file){await openFile(el.dataset.file,el.dataset.isDir==='true');return;}
  if(el.dataset.newFile){newFileForm(el.dataset.newFile);return;}
  if(el.dataset.deleteFile){const name=el.dataset.deleteFile;if(await confirmAction('Datei löschen',`„${name}“ wirklich dauerhaft löschen? Ordner müssen leer sein.`,'Löschen')){await job(api(`/servers/${state.serverId}/files/delete`,'POST',{path:[state.filePath,name].filter(Boolean).join('/')}),20000);toast('Gelöscht.');loadFiles();}return;}
  switch(el.dataset.action){
   case 'menu':$('.sidebar').classList.toggle('open');break;
   case 'create':await openCreate();break;
   case 'pair':await openPair();break;
   case 'pair-done':await closeModal(true);await refresh();navigate('agents');break;
   case 'close':await closeModal();break;
   case 'search':openSearch();break;
   case 'guide':openGuide();break;
   case 'routine':openRoutine();break;
   case 'logout':if(state.demo){toast('Die öffentliche Demo hat keine Anmeldung. Echtbetrieb ohne --demo starten.');}else{await api('/logout','POST');showLogin();}break;
   case 'refresh':await refresh();toast('Ansicht aktualisiert.');break;
   case 'logs':await loadLogs();break;
   case 'retry-install':{const id=state.serverId;if(await confirmAction('Installation wiederholen', 'Zuerst Java/Download und das Agenten-Datenverzeichnis prüfen. Fehlende JAR-Dateien werden heruntergeladen. Eine vorhandene lesbare JAR und vorhandene Konfigurationen bleiben erhalten und werden der gleichen Instanz wieder zugeordnet. Die Softwareversion muss zu diesen Dateien passen.', 'Wiederholen')){el.disabled=true;try{await api(`/servers/${id}/install`,'POST');await refresh(false);if(state.serverId===id)renderDetail();toast('Installation erneut angefordert. Der Status zeigt das Ergebnis.');}finally{el.disabled=false;}}break;}
   case 'zoom-in':state.zoom=Math.min(1.6,state.zoom+.15);updateGraph();break;
   case 'zoom-out':state.zoom=Math.max(.55,state.zoom-.15);updateGraph();break;
   case 'reset-graph':savedPositions={};state.zoom=1;localStorage.removeItem('nova-positions');drawGraph();toast('Node-Anordnung zurückgesetzt.');break;
   case 'copy-token':{const text=$('#pair-token').textContent;try{await navigator.clipboard.writeText(text);toast('Code kopiert.');}catch{const range=document.createRange();range.selectNodeContents($('#pair-token'));getSelection().removeAllRanges();getSelection().addRange(range);toast('Code markiert. Mit Strg+C kopieren.');}break;}
   case 'sync':if(await confirmAction('Minecraft-Netzwerk verknüpfen','Die Velocity-Konfiguration wird gesichert und neu geschrieben; Paper Modern Forwarding wird aktiviert. Alle Instanzen müssen gestoppt sein. Backend-Ports vorher ausschließlich für den Proxy freigeben.','Verknüpfen')){const result=await api('/network/sync','POST');toast(`${result.jobs.length} Konfigurationsaufträge eingereiht. Ergebnisse unter Aktivitäten prüfen.`);await refresh();}break;
   case 'file-up':await loadFiles(state.filePath.split('/').slice(0,-1).join('/'));break;
   case 'reload-files':await loadFiles();break;
   case 'editor-back':if(!state.dirty||await confirmAction('Änderungen verwerfen?','Die Datei enthält ungespeicherte Änderungen.','Verwerfen'))loadFiles();break;
   case 'cancel-new-file':$('#file-create').innerHTML='';break;
   case 'upload':$('#upload-file').click();break;
   case 'save-file':{el.disabled=true;try{const id=state.serverId,path=state.editorPath;await job(api(`/servers/${id}/files/write`,'POST',{path,content:$('#file-editor').value}),30000);state.dirty=false;if($('#editor-status'))$('#editor-status').textContent='Gespeichert · '+new Date().toLocaleTimeString('de-DE');toast('Datei gespeichert.');}finally{el.disabled=false;}break;}
   case 'delete-server':{const s=server(state.serverId);if(await confirmAction('Instanz entfernen',`„${s.name}“ aus NOVA entfernen? Die Dateien auf dem Agenten bleiben erhalten.`,'Entfernen')){await job(api('/servers/'+s.id,'DELETE'));await closeModal(true);await refresh();toast('Instanz entfernt. Dateien wurden behalten.');}break;}
  }
 }catch(err){toast(err.message,true);}
});
document.addEventListener('keydown',e=>{
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(state.data&&!state.dirty)openSearch();}
 if(e.key==='Escape'&&state.modal&&!$('#confirm-dialog').open)closeModal();
 if(e.key==='Tab'&&state.modal&&!$('#confirm-dialog').open){const focusables=$$('button:not(:disabled),input:not(:disabled):not([hidden]),select:not(:disabled),textarea,a[href]', $('.modal')).filter(x=>x.offsetParent!==null);if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('.modal'))){first.focus();e.preventDefault();}}
 if((e.ctrlKey||e.metaKey)&&e.key==='s'&&$('#file-editor')){e.preventDefault();$('[data-action="save-file"]').click();}
});
window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(names[view]&&state.data&&state.view!==view){state.view=view;renderView();}});
async function boot(){const session=await api('/session');state.demo=session.demo;if(!session.authenticated){showLogin();return;}state.data=await api('/overview');state.view=names[location.hash.slice(1)]?location.hash.slice(1):'dashboard';shell();renderView();}
try{if(localStorage.getItem('nova-motion')==='false')document.body.classList.add('no-motion');}catch{}
boot().catch(err=>{$('#app').innerHTML=`<div class="login-page"><div class="login-card"><div class="brand">${mark}NOVA</div><h1>Zentrale nicht erreichbar.</h1><p>${esc(err.message)}</p><a class="button primary" href="/">Erneut verbinden</a></div></div>`;});
setInterval(()=>{if(state.data&&!document.hidden)refresh(state.modal?false:'passive').catch(err=>toast(err.message,true));},8000);
